nodes.func:
msg.payload = { status: 'success', job: 'maintain_iotawatt_retention', completed_at: new Date().toISOString() };
node.status({fill:'green',shape:'dot',text:'archive + prune succeeded'});
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const row = rows[0] || {};
const archiveAge = Number(row.ArchiveAgeHours);
const pruneAge = Number(row.PruneAgeHours);
const pruningEnabled = Number(row.PruningEnabled) === 1 || row.PruningEnabled === true;
const archiveStale = !row.LastArchiveSuccessUTC || !Number.isFinite(archiveAge) || archiveAge > 36;
const pruneStale = pruningEnabled && (!row.LastPruneSuccessUTC || !Number.isFinite(pruneAge) || pruneAge > 36);
const stale = archiveStale || pruneStale;

if (!stale) {
    const pruneText = pruningEnabled ? `${pruneAge}h` : 'disabled';
    node.status({fill:'green',shape:'dot',text:`archive ${archiveAge}h, prune ${pruneText}`});
    msg.payload = {
        status: 'healthy',
        archive_age_hours: archiveAge,
        prune_age_hours: pruningEnabled ? pruneAge : null,
        pruning_enabled: pruningEnabled,
        last_archive_utc: row.LastArchiveSuccessUTC,
        last_prune_utc: row.LastPruneSuccessUTC
    };
    return [null, msg];
}

node.status({fill:'red',shape:'ring',text:'retention stale'});
const now = Date.now();
const lastAlert = flow.get('iotawattRetentionLastStaleAlert') || 0;
if (now - lastAlert < 12 * 60 * 60 * 1000) return [null, null];
flow.set('iotawattRetentionLastStaleAlert', now);
msg.title = 'IotaWatt retention is stale';
msg.payload = `IotaWatt retention health failed. Archive last success UTC: ${row.LastArchiveSuccessUTC || 'never'} (age ${Number.isFinite(archiveAge) ? archiveAge : 'unknown'}h). Prune enabled: ${pruningEnabled}. Prune last success UTC: ${row.LastPruneSuccessUTC || 'never'} (age ${Number.isFinite(pruneAge) ? pruneAge : 'unknown'}h).`;
msg.device = global.get('BradPhoneNM') || 'pixel8';
return [msg, null];

const detail = (msg.error && msg.error.message) ? msg.error.message : String(msg.payload || 'unknown database error');
const now = Date.now();
const lastAlert = flow.get('iotawattRetentionLastErrorAlert') || 0;
if (now - lastAlert < 30 * 60 * 1000) return null;
flow.set('iotawattRetentionLastErrorAlert', now);
msg.title = 'IotaWatt retention failure';
msg.payload = `IotaWatt archive/prune/watchdog database error: ${detail}. Guarded pruning stops on validation failure.`;
msg.device = global.get('BradPhoneNM') || 'pixel8';
return msg;
